// NewHeadStats returns a new HeadStats object.
func NewHeadStats() *HeadStats {
	return &HeadStats{
		WALReplayStatus: &WALReplayStatus{},
	}
}

// WALReplayStatus contains status information about the WAL replay.
type WALReplayStatus struct {
	sync.RWMutex
	Min     int
	Max     int
	Current int
}

// GetWALReplayStatus returns the WAL replay status information.
func (s *WALReplayStatus) GetWALReplayStatus() WALReplayStatus {
	s.RLock()
	defer s.RUnlock()

	return WALReplayStatus{
		Min:     s.Min,
		Max:     s.Max,
		Current: s.Current,
	}
}

const cardinalityCacheExpirationTime = time.Duration(30) * time.Second

// Init loads data from the write ahead log and prepares the head for writes.
// It should be called before using an appender so that it
// limits the ingested samples to the head min valid time.
func (h *Head) Init(minValidTime int64) error {
	h.minValidTime.Store(minValidTime)
	defer func() {
		h.postings.EnsureOrder()
	}()
	defer h.gc() // After loading the wal remove the obsolete data from the head.
	defer func() {
		// Loading of m-mapped chunks and snapshot can make the mint of the Head
		// to go below minValidTime.
		if h.MinTime() < h.minValidTime.Load() {
			h.minTime.Store(h.minValidTime.Load())
		}
	}()

	level.Info(h.logger).Log("msg", "Replaying on-disk memory mappable chunks if any")
	start := time.Now()

	snapIdx, snapOffset := -1, 0
	refSeries := make(map[chunks.HeadSeriesRef]*memSeries)

	if h.opts.EnableMemorySnapshotOnShutdown {
		level.Info(h.logger).Log("msg", "Chunk snapshot is enabled, replaying from the snapshot")
		var err error
		snapIdx, snapOffset, refSeries, err = h.loadChunkSnapshot()
		if err != nil {
			snapIdx, snapOffset = -1, 0
			refSeries = make(map[chunks.HeadSeriesRef]*memSeries)

			h.metrics.snapshotReplayErrorTotal.Inc()
			level.Error(h.logger).Log("msg", "Failed to load chunk snapshot", "err", err)
			// We clear the partially loaded data to replay fresh from the WAL.
			if err := h.resetInMemoryState(); err != nil {
				return err
			}
		}
		level.Info(h.logger).Log("msg", "Chunk snapshot loading time", "duration", time.Since(start).String())
	}

	mmapChunkReplayStart := time.Now()
	mmappedChunks := map[chunks.HeadSeriesRef][]*mmappedChunk{}
	oooMmappedChunks := map[chunks.HeadSeriesRef][]*mmappedChunk{}
	var lastMmapRef, lastRef chunks.ChunkDiskMapperRef
	loadOnDiskChunks := func() error {
		return h.chunkDiskMapper.IterateAllChunks(func(seriesRef chunks.HeadSeriesRef, chunkRef chunks.ChunkDiskMapperRef, mint, maxt int64, numSamples uint16, encoding chunkenc.Encoding) error {
			lastRef = chunkRef
			isOOO := chunkenc.IsOutOfOrderChunk(encoding)
			if isOOO || maxt >= h.minValidTime.Load() {
				if chunkenc.IsValidEncoding(encoding) {
					ms, ok := refSeries[seriesRef]
					if isOOO {
						if !ok {
							oooMmappedChunks[seriesRef] = append(oooMmappedChunks[seriesRef], &mmappedChunk{
								ref:        chunkRef,
								minTime:    mint,
								maxTime:    maxt,
								numSamples: numSamples,
							})
							return nil
						}
						h.metrics.chunks.Inc()
						h.metrics.chunksCreated.Inc()
						if ms.ooo == nil {
							ms.ooo = &memSeriesOOOFields{}
						}
						ms.ooo.oooMmappedChunks = append(ms.ooo.oooMmappedChunks, &mmappedChunk{
							ref:        chunkRef,
							minTime:    mint,
							maxTime:    maxt,
							numSamples: numSamples,
						})
						return nil
					}
					if !ok {
						slice := mmappedChunks[seriesRef]
						if len(slice) > 0 {
							if slice[len(slice)-1].maxTime >= mint {
								h.metrics.mmapChunkCorruptionTotal.Inc()
								return errors.Errorf("out of sequence m-mapped chunk for series ref %d, last chunk: [%d, %d], new: [%d, %d]",
									seriesRef, slice[len(slice)-1].minTime, slice[len(slice)-1].maxTime, mint, maxt)
							}
						}
						slice = append(slice, &mmappedChunk{
							ref:        chunkRef,
							minTime:    mint,
							maxTime:    maxt,
							numSamples: numSamples,
						})
						mmappedChunks[seriesRef] = slice
						return nil
					}
					if len(ms.mmappedChunks) > 0 {
						if ms.mmappedChunks[len(ms.mmappedChunks)-1].maxTime >= mint {
							h.metrics.mmapChunkCorruptionTotal.Inc()
							return errors.Errorf("out of sequence m-mapped chunk for series ref %d, last chunk: [%d, %d], new: [%d, %d]",
								seriesRef, ms.mmappedChunks[len(ms.mmappedChunks)-1].minTime, ms.mmappedChunks[len(ms.mmappedChunks)-1].maxTime,
								mint, maxt)
						}
					}
					h.metrics.chunks.Inc()
					h.metrics.chunksCreated.Inc()
					ms.mmappedChunks = append(ms.mmappedChunks, &mmappedChunk{
						ref:        chunkRef,
						minTime:    mint,
						maxTime:    maxt,
						numSamples: numSamples,
					})
					h.updateMinMaxTime(mint, maxt)
					if ms.headChunk != nil {
						if maxt >= ms.headChunk.minTime {
							// The head chunk was completed and was m-mapped after taking the snapshot.
							// Hence remove this chunk.
							ms.nextAt = 0
							ms.headChunk = nil
							ms.app = nil
						}
					}
					return nil
				}
			}
			return nil
		})
	}
	err := loadOnDiskChunks()
	if err != nil {
		err = errors.Wrap(err, "iterate on on-disk chunks")
		// TODO(codesome): clear out all m-map chunks here for refSeries.
		level.Error(h.logger).Log("msg", "Loading on-disk chunks failed", "err", err)
		if _, ok := errors.Cause(err).(*chunks.CorruptionErr); ok {
			h.metrics.mmapChunkCorruptionTotal.Inc()
		}

		// Discard snapshot data since we need to replay the WAL for the missed m-map chunks data.
		snapIdx, snapOffset = -1, 0

		// If this fails, data will be recovered from WAL.
		// Hence we wont lose any data (given WAL is not corrupt).
		level.Info(h.logger).Log("msg", "Deleting mmapped chunk files")
		if resetErr := h.resetInMemoryState(); resetErr != nil {
			return resetErr
		}

		level.Info(h.logger).Log("msg", "Deleting mmapped chunk files")

		mmapErr := err
		if delErr := h.chunkDiskMapper.DeleteCorrupted(mmapErr); delErr != nil {
			level.Info(h.logger).Log("msg", "Deletion of corrupted mmap chunk files failed, discarding chunk files completely", "err", delErr)
			if truncErr := h.chunkDiskMapper.Truncate(math.MaxUint32); truncErr != nil {
				level.Error(h.logger).Log("msg", "Deletion of all mmap chunk files failed", "err", truncErr)
			}
			mmappedChunks = map[chunks.HeadSeriesRef][]*mmappedChunk{}
			oooMmappedChunks = map[chunks.HeadSeriesRef][]*mmappedChunk{}
			lastMmapRef = 0
		} else {
			level.Info(h.logger).Log("msg", "Deletion of mmap chunk files successful, reattempting m-mapping the on-disk chunks")
			var retryErr error
			mmappedChunks, oooMmappedChunks, lastMmapRef, retryErr = h.loadMmappedChunks(make(map[chunks.HeadSeriesRef]*memSeries))
			if retryErr != nil {
				level.Error(h.logger).Log("msg", "Loading on-disk chunks failed, discarding chunk files completely", "err", retryErr)
				if truncErr := h.chunkDiskMapper.Truncate(math.MaxUint32); truncErr != nil {
					level.Error(h.logger).Log("msg", "Deletion of all mmap chunk files failed after failed loading", "err", truncErr)
				}
				mmappedChunks = map[chunks.HeadSeriesRef][]*mmappedChunk{}
			}
		}
	} else {
		lastMmapRef = lastRef
	}

	level.Info(h.logger).Log("msg", "On-disk memory mappable chunks replay completed", "duration", time.Since(mmapChunkReplayStart).String())
	if h.wal == nil {
		level.Info(h.logger).Log("msg", "WAL not found")
		return nil
	}

